// Radix UI (ou dialog HTML nativo) faz isso automaticamente
import { Dialog } from '@radix-ui/react-dialog';

<Dialog.Root>
  <Dialog.Trigger>Abrir</Dialog.Trigger>
  <Dialog.Portal>
    <Dialog.Overlay className="..." />
    <Dialog.Content className="...">
      {/* Focus trap automático */}
      {/* Esc fecha automático */}
      {/* Click overlay fecha automático */}
      {/* Focus restaurado após close */}
      <Dialog.Title>Título</Dialog.Title>
      <Dialog.Description>...</Dialog.Description>
      <Dialog.Close>Fechar</Dialog.Close>
    </Dialog.Content>
  </Dialog.Portal>
</Dialog.Root>

// Layout.tsx — primeiro elemento focável
<a
  href="#main-content"
  className="skip-link"  // invisível até focus
>
  Pular para conteúdo
</a>
<header>...</header>
<main id="main-content">...</main>

// CSS
.skip-link {
  position: absolute;
  left: -9999px;
  top: 0;
}
.skip-link:focus {
  left: 10px;
  z-index: 9999;
  background: white;
  padding: 8px 16px;
}
